"""A simple reference simulation of the documented client replay rules."""
import heapq

def fp(data):
    h = 0
    for b in data:
        h = (h*257 + b + 1) & ((1 << 64) - 1)
    return {'n': len(data), 'h': '%016x' % h}

def receipt(entries):
    out = b''
    for at, stream, kind, data, end in entries:
        out += at.to_bytes(8,'big') + stream.to_bytes(4,'big') + kind.encode('ascii')
        if kind in ('H','h'):
            out += len(data).to_bytes(8,'big')
            for n,v in data:
                out += len(n).to_bytes(8,'big') + n + len(v).to_bytes(8,'big') + v
        else:
            out += len(data).to_bytes(8,'big') + data
        out += bytes([1 if end else 0])
    return out

def simulate(cases, events, timeout_ms):
    """cases: list of frame lists (dicts with Type/data_to_transfered/End_Stream/Time_to_Stop)
       events: list of dicts (at, kind, stream, fields/data, end)"""
    state = []
    for index, frames in enumerate(cases):
        state.append({'index':index,'pos':0,'closed':False,'sending':True,'ended':False,
                      'terminal':None,'at':0,'recv':[],'sent':[],'frames':0,'req':0,'payload':0})
    heap = []
    ordered = sorted(range(len(events)), key=lambda i: (events[i]['at'], i))
    ei = 0
    time = [0]

    def advance(case):
        frames = cases[case['index']]
        while case['pos'] < len(frames):
            frame = frames[case['pos']]
            case['pos'] += 1
            kind = frame['Type']
            if kind == 'sleep':
                heapq.heappush(heap, (time[0] + frame['Time_to_Stop'], 1, case['index'], ('pause', case)))
                return
            if case['closed']:
                case['terminal'] = 'send_error'; case['at'] = time[0]; return
            case['frames'] += 1
            if kind == 'headers':
                case['req'] += 1
                case['payload'] += sum(len(n)+len(v) for n, v in frame['data_to_transfered'])
                case['sent'].append((time[0], 4*case['index'], 'H', frame['data_to_transfered'], frame['End_Stream']))
                if frame['End_Stream']:
                    case['closed'] = True
            elif kind == 'data':
                case['req'] += 1
                case['payload'] += len(frame['data_to_transfered'])
                case['sent'].append((time[0], 4*case['index'], 'D', frame['data_to_transfered'], frame['End_Stream']))
                if frame['End_Stream']:
                    case['closed'] = True
            else:
                case['payload'] += len(frame['data_to_transfered'])
                case['sent'].append((time[0], 4*case['index'], 'G', frame['data_to_transfered'], False))
        case['sending'] = False
        if case['ended']:
            case['terminal'] = 'ok'; case['at'] = time[0]
        else:
            heapq.heappush(heap, (time[0] + timeout_ms, 2, case['index'], ('timeout', case)))

    def handle(event):
        if event['kind'] == 'close':
            for case in state:
                if case['terminal'] is None:
                    case['terminal'] = 'closed'; case['at'] = time[0]
            return
        stream = event['stream']
        if stream % 4 or stream // 4 >= len(state):
            return
        case = state[stream // 4]
        if case['terminal'] is not None or case['ended']:
            return
        if event['kind'] == 'headers':
            case['recv'].append((time[0], stream, 'h', event['fields'], event['end']))
        else:
            case['recv'].append((time[0], stream, 'd', event['data'], event['end']))
        if event['end']:
            case['ended'] = True
            if not case['sending']:
                case['terminal'] = 'ok'; case['at'] = time[0]

    for case in state:
        advance(case)
    while True:
        candidates = []
        if heap:
            candidates.append(heap[0][0])
        if ei < len(ordered):
            candidates.append(events[ordered[ei]]['at'])
        if not candidates:
            break
        time[0] = min(candidates)
        while ei < len(ordered) and events[ordered[ei]]['at'] == time[0]:
            handle(events[ordered[ei]]); ei += 1
        while heap and heap[0][0] == time[0]:
            _, kind, _, item = heapq.heappop(heap)
            case = item[1]
            if case['terminal'] is not None:
                continue
            if item[0] == 'pause':
                advance(case)
            else:
                case['terminal'] = 'timeout'; case['at'] = time[0]
    out = []
    for case in state:
        body = b''.join(data for _, _, kind, data, _ in case['recv'] if kind == 'd')
        out.append({'state':case['terminal'],'at':case['at'],'frames':case['frames'],
                    'request_frames':case['req'],'payload_bytes':case['payload'],
                    'sent':fp(receipt(case['sent'])),'received':fp(receipt(case['recv'])),
                    'response_frames':len(case['recv']),'response_body':fp(body)})
    return out
